import re
from urllib.parse import parse_qs

# WAF de juguete. Uno real (ModSecurity + reglas CRS) tiene cientos
# de reglas; aquí solo miramos los parámetros de una petición GET.
NEGRA = {"SQLi": r"'.*\b(or|and)\b|union\s+select",  # firmas de
         "XSS": r"<\s*script"}                        # ataques
BLANCA = {"q": r"[\w ]{1,40}",                  # lo que SÍ se acepta
          "user": r"[a-z0-9_]{3,20}",            # en cada campo
          "concepto": r"[\w '.,-]{1,60}"}

def lista_negra(params):
    for campo, v in params.items():
        for ataque, firma in NEGRA.items():
            if re.search(firma, v, re.I):
                return f"BLOQUEA ({ataque})"
    return "pasa"

def lista_blanca(params):
    ok = all(c in BLANCA and re.fullmatch(BLANCA[c], v)
             for c, v in params.items())
    return "pasa" if ok else "BLOQUEA"

for query in ["q=zapatillas rojas",
              "user=admin' OR '1'='1",
              "q=<script>alert(1)</script>",
              "concepto=Libros de O'Reilly or Anaya",
              "q=<img src=x onerror=alert(1)>"]:
    p = {k: v[0] for k, v in parse_qs(query).items()}
    print(f"{query[:30]:<31}| negra: {lista_negra(p):<15}"
          f"| blanca: {lista_blanca(p)}")
